// Wire protocol v3 and relay/v1 (docs/mobile-contract.md §2-§5), generated by
// hand from pkg/remote/wire/v3.go, relay.go and the fixtures in
// pkg/remote/wire/testdata/v3_*.json and relay_*.json.
// Same round-trip rule as v2: every decoder builds a fresh value holding only
// the fields the contract declares, so protocol3.test.ts can re-encode each
// fixture and compare bytes the way the Go test does.
import {
  bool,
  type Decoder,
  decodeApproval,
  decodeResFrame,
  decodeTheme,
  int,
  isRecord,
  list,
  object,
  oneOf,
  raw,
  str,
  time,
} from "./protocol";

export const PROTOCOL_V3 = 3;

// Error codes v3 adds to the v2 set (contract §2).
export const CODE_ASSERTION_REQUIRED = "assertion_required";
export const CODE_ASSERTION_INVALID = "assertion_invalid";
export const CODE_EXPIRED = "expired";

// Close codes the relay adds to the v2 set (contract §5).
export const CLOSE_UNKNOWN_CID = 4404;
export const CLOSE_HOST_REPLACED = 4409;

// ---- frames (inside the Noise channel) -------------------------------------

export interface FocusRef3 {
  project_id: string;
  session_id: string;
}

export const decodeFocusRef3: Decoder<FocusRef3> = object({ project_id: str, session_id: str }, {});

export interface Resume3 {
  epoch: string;
  seq: number;
  focus?: FocusRef3;
}

export const decodeResume3: Decoder<Resume3> = object(
  { epoch: str, seq: int },
  { focus: decodeFocusRef3 },
);

export interface Hello3Frame {
  t: "hello";
  v: 3;
  resume?: Resume3;
}

const v3: Decoder<3> = (v) => (v === 3 ? 3 : null);

export const decodeHello3Frame: Decoder<Hello3Frame> = object(
  { t: oneOf(["hello"] as const), v: v3 },
  { resume: decodeResume3 },
);

