export const HOST_FRAME_TYPES = [
  "challenge",
  "auth",
  "ready",
  "devices",
  "pair_open",
  "pair_close",
  "open",
  "data",
  "close",
  "mail",
  "ack",
  "snap",
  "push",
] as const;

export type HostFrameType = (typeof HOST_FRAME_TYPES)[number];

export interface HostFrame {
  t: HostFrameType;
  nonce?: string;
  sig?: string;
  hashes?: string[];
  pair_id_hash?: string;
  exp?: number;
  lane?: string;
  device?: string;
  pair?: boolean;
  code?: number;
  b64?: string;
  id?: string;
  device_hash?: string;
  ttl?: number;
  urgency?: string;
}

export const decodeHostFrame: Decoder<HostFrame> = object(
  { t: oneOf(HOST_FRAME_TYPES) },
  {
    nonce: str,
    sig: str,
    hashes: list(str),
    pair_id_hash: str,
    exp: int,
    lane: str,
    device: str,
    pair: bool,
    code: int,
    b64: str,
    id: str,
    device_hash: str,
    ttl: int,
    urgency: str,
  },
);

